# frozen_string_literal: true

module RuboCop
  module Cop
    module SpecStyle
      # Flags examples generated by iterating over a collection.
      #
      # Looping over data to define `it`/`context`/`it_behaves_like` blocks
      # trades readability for brevity: the reader has to run the loop in
      # their head, the failure output shows interpolated data instead of a
      # behaviour, and a single case can't be run by line number.
      # Prefer DAMP (Descriptive And Meaningful Phrases) over DRY in specs.
      #
      # @example
      #   # bad
      #   %w[ready seated].each do |status|
      #     it "still counts as a duplicate while the party is #{status}" do
      #       ...
      #     end
      #   end
      #
      #   # good
      #   it "still counts as a duplicate while the party is ready" do
      #     ...
      #   end
      #
      #   it "still counts as a duplicate while the party is seated" do
      #     ...
      #   end
      class NoLoopedExamples < Base
        MSG = "Don't generate examples by looping with `%<method>s`. " \
              "Write each case as its own `it` with its setup and expectations inline, " \
              "even if that repeats a few lines; a spec should read top to bottom. " \
              "Name the behaviour, not the data, and don't interpolate values into " \
              "descriptions. Only use `shared_examples` when the shared body is long. " \
              "Do not silence this cop with a disable comment; restructure the spec instead."

        ITERATORS = %i[each each_with_index each_pair each_with_object each_key each_value times].to_set.freeze

        EXAMPLE_DEFINERS = %i[
          it specify example scenario its
          context describe feature
          it_behaves_like it_should_behave_like include_examples include_context
        ].to_set.freeze

        # @!method defines_example?(node)
        def_node_search :defines_example?, <<~PATTERN
          (send nil? EXAMPLE_DEFINERS ...)
        PATTERN

        def on_block(node)
          send_node = node.send_node
          return unless ITERATORS.include?(send_node.method_name)
          return unless send_node.receiver
          return unless node.body && defines_example?(node.body)

          add_offense(send_node.loc.selector, message: format(MSG, method: send_node.method_name))
        end
        alias on_numblock on_block
        alias on_itblock on_block
      end
    end
  end
end
